import{_ as a,o as t,c as o,a2 as s}from"./chunks/framework.BS0bAV7E.js";const h=JSON.parse('{"title":"L1 guide: writing a module, end to end","description":"","frontmatter":{},"headers":[],"relativePath":"l1/writing-modules.md","filePath":"l1/writing-modules.md"}'),n={name:"l1/writing-modules.md"};function i(l,e,d,r,c,u){return t(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="l1-guide-writing-a-module-end-to-end" tabindex="-1">L1 guide: writing a module, end to end <a class="header-anchor" href="#l1-guide-writing-a-module-end-to-end" aria-label="Permalink to &quot;L1 guide: writing a module, end to end&quot;">​</a></h1><p>A complete walk: source -&gt; surface calls -&gt; load -&gt; run.</p><h2 id="step-1-pick-your-loading-path" tabindex="-1">Step 1 - pick your loading path <a class="header-anchor" href="#step-1-pick-your-loading-path" aria-label="Permalink to &quot;Step 1 - pick your loading path&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Path</th><th>When</th><th>How</th></tr></thead><tbody><tr><td>Compiled-in</td><td>your module ships with a kernel build</td><td>compile in, call your init from kmain or a shell built-in</td></tr><tr><td>Shared object</td><td>deploy without rebuilding</td><td>build a .so, load through the ld.so surface</td></tr><tr><td>Embedded tool</td><td>ship an ELF payload</td><td><code>tool_register(name, elf, size)</code> then <code>run name</code></td></tr></tbody></table><h2 id="step-2-the-surface-you-build-on" tabindex="-1">Step 2 - the surface you build on <a class="header-anchor" href="#step-2-the-surface-you-build-on" aria-label="Permalink to &quot;Step 2 - the surface you build on&quot;">​</a></h2><p>For a module with a shell command and some work:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &quot;l1_ext.h&quot;          /* shell bridge, config, ... */</span></span>
<span class="line"><span>#include &quot;l1_wp8cd.h&quot;        /* shell_register_builtin, jobs */</span></span>
<span class="line"><span></span></span>
<span class="line"><span>static int cmd_mymod(const char *args) {</span></span>
<span class="line"><span>    /* parse args, do the work, print through the console hook */</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>void mymod_init(void) {</span></span>
<span class="line"><span>    l1_ext_shell_register_command_ex(</span></span>
<span class="line"><span>        &quot;mymod&quot;, cmd_mymod, &quot;my module - does the thing&quot;, &quot;L1-demo&quot;);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>For UI: add <code>tui_menu_register</code> / <code>tui_page_register</code>. For storage: <code>driver_block_register</code>. See the family pages.</p><h2 id="step-3-build" tabindex="-1">Step 3 - build <a class="header-anchor" href="#step-3-build" aria-label="Permalink to &quot;Step 3 - build&quot;">​</a></h2><ul><li>Compiled-in: your .c lands in the matching tree directory; the Makefile picks it up by wildcard; register from <code>mymod_init</code>.</li><li>Shared object: build an ELF .so against the surface headers, then in-guest (or from your loader) <code>so_load(name, flags)</code> + <code>symbol_resolve</code>/<code>dlsym_impl</code> for the init symbol - the full mechanics in <a href="./solib-loader.html">solib-loader.md</a>.</li></ul><h2 id="step-4-test-it" tabindex="-1">Step 4 - test it <a class="header-anchor" href="#step-4-test-it" aria-label="Permalink to &quot;Step 4 - test it&quot;">​</a></h2><ul><li><code>run &lt;yourprog&gt;</code> / invoke your command; check <code>help -w</code> shows your tag.</li><li>The full bar from <a href="./../root/CONTRIBUTING.html">CONTRIBUTING.md</a>: the build stays 0-warning, the regression suite still passes 28/28, the command count baseline grows by exactly your commands.</li><li><code>l1test</code> and <code>l1_ext_self_test()</code> exercise the surface itself.</li></ul><h2 id="rules-of-the-road" tabindex="-1">Rules of the road <a class="header-anchor" href="#rules-of-the-road" aria-label="Permalink to &quot;Rules of the road&quot;">​</a></h2><ul><li>ASCII strings only for everything the system prints.</li><li>Bounded tables get named limit constants + loud refusal.</li><li>The docs: your command pages regenerate via <code>make api-docs</code>; the manual chapter for your domain is part of the PR.</li></ul>`,14)])])}const m=a(n,[["render",i]]);export{h as __pageData,m as default};
